with parsed as (select id, plan, currency, discounts, slice(tier_limits, 1, 2) as first_two_limits, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, element_at(tier_prices, 1) as entry_price from price_tiers) select id, currency, entry_price, avg(entry_price) over (partition by currency) currency_avg_entry_price, min(entry_price) over (partition by currency) currency_min_entry_price from parsed;
